async function includePartials(){const nodes=document.querySelectorAll('[data-include]');for(const n of nodes){const url=n.getAttribute('data-include');try{const res=await fetch(url);if(!res.ok)throw new Error(res.status+" "+res.statusText);n.innerHTML=await res.text();}catch(err){n.innerHTML=`<div style="color:var(--muted)">Could not load<code>${url}</code>:${err.message}</div>`;}}}
(function(){const root=document.documentElement;const prefersDark=window.matchMedia('(prefers-color-scheme: dark)').matches;const saved=localStorage.getItem('theme');const start=saved||(prefersDark?'dark':'light');root.setAttribute('data-theme',start);const btn=document.querySelector('#themeToggle, #theme-toggle, .toggle');function setIcon(theme){if(btn)btn.textContent=theme==='dark'?'☀️':'🌙';}
setIcon(start);if(btn){btn.addEventListener('click',()=>{const now=root.getAttribute('data-theme')==='dark'?'light':'dark';root.setAttribute('data-theme',now);localStorage.setItem('theme',now);setIcon(now);});}})();const partialsLoaded=includePartials();document.querySelectorAll('.email-copy').forEach(btn=>{btn.addEventListener('click',async()=>{const email=btn.dataset.email||btn.textContent.trim();try{await navigator.clipboard.writeText(email);const old=btn.textContent;btn.textContent='Copied!';setTimeout(()=>btn.textContent=old,1200);}catch(e){window.prompt('Press Ctrl/Cmd+C to copy:',email);}});});(async function(){const el=document.getElementById('last-updated');if(!el)return;try{const res=await fetch('https://api.github.com/repos/MauriceDHanisch/MauriceDHanisch.github.io/branches/main');if(!res.ok)throw new Error('API Error');const data=await res.json();const lastCommitDate=data.commit.commit.author.date;const date=new Date(lastCommitDate);const options={year:'numeric',month:'long',day:'numeric'};el.innerHTML=`Last updated:&nbsp;&nbsp;${date.toLocaleDateString('en-US',options)}`;}catch(e){const date=new Date(document.lastModified);const options={year:'numeric',month:'long',day:'numeric'};el.innerHTML=`Last updated:&nbsp;&nbsp;${date.toLocaleDateString('en-US',options)}`;}})();(function(){function formatStarCount(n){if(n<1000)return String(n);const k=n/1000;return(k>=10?Math.round(k):k.toFixed(1).replace(/\.0$/,''))+'k';}
async function loadStarCounts(){const nodes=document.querySelectorAll('[data-stars-repo]');for(const el of nodes){const[host,path]=el.dataset.starsRepo.split(':');const countEl=el.querySelector('.oss-star-count');if(!countEl)continue;try{let count;if(host==='github'){const res=await fetch('https://api.github.com/repos/'+path);if(!res.ok)throw new Error(String(res.status));count=(await res.json()).stargazers_count;}else if(host==='gitlab'){const res=await fetch('https://gitlab.com/api/v4/projects/'+encodeURIComponent(path));if(!res.ok)throw new Error(String(res.status));count=(await res.json()).star_count;}else{continue;}
countEl.textContent=formatStarCount(count);}catch(e){el.hidden=true;}}}
partialsLoaded.then(loadStarCounts);})();